@@ -0,0 +1,11 @@
+import { slugify } from "../lib/text.js";
+import { formatDate } from "../lib/date.js";
+
+export function createEventCard(event) {
+  const title = typeof event?.title === "string" ? event.title.trim() : "";
+  if (!title) throw new TypeError("Event title is required");
+  const id = slugify(title);
+  if (!id) throw new TypeError("Event title must contain letters or digits");
+  if (event.startsAt == null) throw new TypeError("Invalid event date");
+  return { id, title, dateLabel: formatDate(event.startsAt) };
+}

